import{_ as n,o as i,c as t,ah as s}from"./chunks/framework.DDXs_i7t.js";const k=JSON.parse('{"title":"Drehbuch-Updates: Zentrale Szenen übersetzt","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/szene-updates.md","filePath":"logbuch/szene-updates.md"}'),r={name:"logbuch/szene-updates.md"};function a(d,e,h,o,l,u){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="drehbuch-updates-zentrale-szenen-ubersetzt" tabindex="-1">Drehbuch-Updates: Zentrale Szenen übersetzt <a class="header-anchor" href="#drehbuch-updates-zentrale-szenen-ubersetzt" aria-label="Permalink to &quot;Drehbuch-Updates: Zentrale Szenen übersetzt&quot;">​</a></h1><p>Wir haben mehrere Schlüsselszenen dokumentiert, die den Ton der Mockumentary definieren. Hier ist eine Zusammenfassung der neuesten Updates:</p><h3 id="szene-15-das-protokoll-des-schweigens" tabindex="-1">Szene 15: Das Protokoll des Schweigens <a class="header-anchor" href="#szene-15-das-protokoll-des-schweigens" aria-label="Permalink to &quot;Szene 15: Das Protokoll des Schweigens&quot;">​</a></h3><p>Ein düsterer, bürokratischer Tanz in den Archiven von Duisburg (1936). Die Namen der Vorgänger werden mit erschreckender Effizienz ausradiert.</p><h3 id="szene-22-die-emoji-lektion" tabindex="-1">Szene 22: Die Emoji-Lektion <a class="header-anchor" href="#szene-22-die-emoji-lektion" aria-label="Permalink to &quot;Szene 22: Die Emoji-Lektion&quot;">​</a></h3><p>Eine moderne Satire. Politische Berater diskutieren, wie man Millionen-Tranchen in WhatsApp-Chats nur mit Emojis beschreibt, um den Rechnungshof zu umgehen.</p><h3 id="szene-31-die-kunst-der-gefalligkeit" tabindex="-1">Szene 31: Die Kunst der Gefälligkeit <a class="header-anchor" href="#szene-31-die-kunst-der-gefalligkeit" aria-label="Permalink to &quot;Szene 31: Die Kunst der Gefälligkeit&quot;">​</a></h3><p>Heidi Horten erklärt ihre Philosophie des „Gebens“. Jede Spende ist ein Pinselstrich in ihrem pointillistischen Meisterwerk der Einflussnahme.</p><h3 id="szene-42-die-asthetik-der-kleinigkeit" tabindex="-1">Szene 42: Die Ästhetik der Kleinigkeit <a class="header-anchor" href="#szene-42-die-asthetik-der-kleinigkeit" aria-label="Permalink to &quot;Szene 42: Die Ästhetik der Kleinigkeit&quot;">​</a></h3><p>Eine Studie über Tranchen. Warum 49.000 schöner ist als 50.000. Eine Lektion in mathematischer Unsichtbarkeit.</p><h3 id="szene-50-das-ewige-schaufenster" tabindex="-1">Szene 50: Das ewige Schaufenster <a class="header-anchor" href="#szene-50-das-ewige-schaufenster" aria-label="Permalink to &quot;Szene 50: Das ewige Schaufenster&quot;">​</a></h3><p>Helmut Horten steht vor seinem ersten „erworbenen“ Kaufhaus. Er sieht nicht die Vergangenheit, sondern eine endlose Zukunft des Konsums.</p><p><em>Diese Szenen werden nun in das vollständige Drehbuch integriert.</em></p>',13)])])}const m=n(r,[["render",a]]);export{k as __pageData,m as default};
